<?php
/** Proof — milestones (spec "Proof", 3): M1 planned → delivered → accepted with a note and a file; accept without a note → 422; amount change on accepted → 422; cancel with a reason; delete a planned one only. */
require __DIR__ . '/lib.php';
$marco = as_member(27); $priya = as_member(26);
[$beta, ] = fixture_client('SMOKE Beta', 'BETA');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $beta, 'name' => 'SMOKE Beta fixed', 'kind' => 'fixed_bid', 'budget_amount' => '30000', 'billing_cadence' => 'on_milestone', 'start_now' => 'yes']);
$eng = (int) $b['record_id'];

echo "1. Add\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['engagement' => $eng, 'name' => 'SMOKE M1 Discovery', 'amount' => '10000', 'due_date' => '2026-04-30']);
$m1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $m1 > 0 && str_ends_with((string) $b['location'], '/engagements/' . $eng . '/milestones?notice=milestone#milestone-card-' . $m1), "milestone_save: record_id $m1, lands on the milestones tab");
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['engagement' => $eng, 'name' => 'SMOKE M2 Build', 'amount' => '20000']);
$m2 = (int) $b['record_id'];
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['engagement' => $eng, 'name' => 'SMOKE M3 Deliverable']);
$m3 = (int) $b['record_id'];
ok($c === 200 && (string) one('SELECT amount FROM milestones WHERE id = :m', ['m' => $m3]) === '0.00' && q('SELECT sort_order FROM milestones WHERE engagement_id = :e ORDER BY id', ['e' => $eng]) === [['sort_order' => 1], ['sort_order' => 2], ['sort_order' => 3]], 'three milestones, numbered in order; the third has no amount');
$log = activity('milestone.save', $since);
ok(count($log) === 3 && (int) $log[0]['engagement_id'] === $eng && json_decode((string) $log[0]['after'], true) == ['name' => 'SMOKE M1 Discovery', 'amount' => '10000.00', 'due_date' => '2026-04-30', 'sort_order' => 1, 'currency' => 'USD'], 'milestone.save logged with the engagement\'s keys and the record');
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['milestone' => $m1, 'due_date' => '2026-05-15']);
ok($c === 200 && q('SELECT name, amount, due_date FROM milestones WHERE id = :m', ['m' => $m1])[0] === ['name' => 'SMOKE M1 Discovery', 'amount' => '10000.00', 'due_date' => '2026-05-15'], 'a change keeps what it is not sent');
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['engagement' => $eng, 'name' => 'SMOKE bad', 'amount' => '-1']);
ok($c === 422 && isset(fields($b)['amount']), 'a negative amount: 422');

echo "2. Deliver and accept\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/milestones/deliver.php', ['milestone' => $m1, 'note' => 'SMOKE sent the report']);
ok($c === 200 && q('SELECT status, delivered_at IS NOT NULL AS d FROM milestones WHERE id = :m', ['m' => $m1])[0] === ['status' => 'delivered', 'd' => true] && count(activity('milestone.deliver', $since)) === 1, 'M1 delivered, logged');
[$c, $b] = act($marco, '/engagements/milestones/deliver.php', ['milestone' => $m1]);
ok($c === 422 && str_contains(msg($b), 'is already delivered'), 'delivering it again: 422 in words' . ($c === 422 ? ' (' . msg($b) . ')' : " (got $c)"));
[$c, $b] = act($marco, '/engagements/milestones/accept.php', ['milestone' => $m1]);
ok($c === 422 && isset(fields($b)['acceptance_note']), 'accept without a note: 422 (field acceptance_note)');
$tmp = tempnam(sys_get_temp_dir(), 'ctev') . '.pdf';
file_put_contents($tmp, "%PDF-1.4\n%SMOKE signed acceptance\n");
$since = last_activity_id();
[$c, $b] = upload($marco, '/engagements/milestones/accept.php', ['milestone' => $m1, 'acceptance_note' => 'SMOKE Jo (AP) by email on Apr 28'], 'file', $tmp, 'SMOKE acceptance.pdf');
$aid = (int) ($b['attachment_id'] ?? 0);
ok($c === 200 && $aid > 0 && q('SELECT status, accepted_by, acceptance_note, accepted_at IS NOT NULL AS a FROM milestones WHERE id = :m', ['m' => $m1])[0] === ['status' => 'accepted', 'accepted_by' => 27, 'acceptance_note' => 'SMOKE Jo (AP) by email on Apr 28', 'a' => true], 'accepted with a note and the evidence file; accepted_by defaults to Marco');
ok(q("SELECT record_type, record_id, client_visible FROM attachments WHERE id = :a", ['a' => $aid])[0] === ['record_type' => 'milestone', 'record_id' => $m1, 'client_visible' => false], 'the evidence is an attachment of the milestone, not client-visible');
$log = activity('milestone.accept', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['attachment_id'] === $aid && json_decode((string) $log[0]['after'], true)['amount'] === '10000.00', 'milestone.accept logged with the attachment and the amount');
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['milestone' => $m1, 'amount' => '12000']);
ok($c === 422 && msg($b) === "An accepted milestone's amount is fixed", 'changing an accepted amount: the guard\'s words');
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['milestone' => $m1, 'description' => 'SMOKE still editable']);
ok($c === 200, 'its description still changes');
[$c, $b] = act($marco, '/engagements/milestones/accept.php', ['milestone' => $m2, 'acceptance_note' => 'SMOKE accepted straight from planned', 'accepted_by' => 28]);
ok($c === 200 && (int) one('SELECT accepted_by FROM milestones WHERE id = :m', ['m' => $m2]) === 28, 'a planned milestone may be accepted directly, naming who recorded it (Bea)');
[$c, $b] = act($marco, '/engagements/milestones/delete.php', ['milestone' => $m2]);
ok($c === 422 && str_contains(msg($b), 'is accepted; only a planned one is deleted'), 'deleting an accepted one: 422 in words');

echo "3. Cancel and delete\n";
[$c, $b] = act($marco, '/engagements/milestones/cancel.php', ['milestone' => $m3]);
ok($c === 422 && isset(fields($b)['reason']), 'cancel without a reason: 422');
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/milestones/cancel.php', ['milestone' => $m3, 'reason' => 'SMOKE descoped']);
ok($c === 200 && q('SELECT status, cancel_reason FROM milestones WHERE id = :m', ['m' => $m3])[0] === ['status' => 'cancelled', 'cancel_reason' => 'SMOKE descoped'] && count(activity('milestone.cancel', $since)) === 1, 'cancelled with the reason, logged');
[$c, $b] = act($marco, '/engagements/milestones/deliver.php', ['milestone' => $m3]);
ok($c === 422 && str_contains(msg($b), 'is cancelled'), 'a cancelled one stays so');
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['engagement' => $eng, 'name' => 'SMOKE M4 to delete']);
$m4 = (int) $b['record_id'];
[$c, $b] = act($marco, '/engagements/notes/save.php', ['record_type' => 'milestone', 'record' => $m4, 'body' => 'SMOKE a note on M4']);
ok($c === 200 && ($b['location'] ?? '') === '/engagements/' . $eng . '/milestones?notice=noted#notes', 'a note on a milestone lands on the engagement\'s milestones tab');
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/milestones/delete.php', ['milestone' => $m4]);
ok($c === 200 && (int) one('SELECT count(*) FROM milestones WHERE id = :m', ['m' => $m4]) === 0 && (int) one("SELECT count(*) FROM notes WHERE record_type = 'milestone' AND record_id = :m", ['m' => $m4]) === 0 && count(activity('milestone.delete', $since)) === 1, 'a planned one deleted with its note, logged');
[$c, $d] = screen($marco, '/engagements/' . $eng . '/milestones');
ok($c === 200 && count($d['engagement']['milestones']) === 3 && $d['engagement']['milestones'][0]['status'] === 'accepted' && $d['engagement']['milestones'][0]['accepted_by']['display_name'] === 'SMOKE Marco', 'the tab lists three with their states');
[$c, $b] = act($priya, '/engagements/milestones/save.php', ['engagement' => $eng, 'name' => 'SMOKE by Priya']);
ok($c === 403, 'a Consultant may not add a milestone: 403');
@unlink($tmp);
finish();
